INSERT INTO `seo_settings` (`id`, `entity_type`, `entity_id`, `seo_title`, `meta_description`, `focus_keyword`, `secondary_keywords`, `canonical_url`, `robots`, `og_title`, `og_description`, `og_image`, `twitter_title`, `twitter_description`, `twitter_image`, `schema_type`, `breadcrumb_title`, `image_alt_text`) VALUES (1,'tool',1,'Salary Calculator — Free Online Tool','Calculate your estimated net salary after tax and deductions.','salary calculator',NULL,NULL,'index,follow',NULL,NULL,NULL,NULL,NULL,NULL,'WebApplication',NULL,'Salary Calculator'),
(2,'tool',2,'Overtime Calculator — Free Online Tool','Calculate overtime pay based on your hourly rate and multiplier.','overtime calculator',NULL,NULL,'index,follow',NULL,NULL,NULL,NULL,NULL,NULL,'WebApplication',NULL,'Overtime Calculator'),
(3,'tool',3,'Working Hours Calculator — Free Online Tool','Calculate total hours worked between a start and end time, minus breaks.','working hours calculator',NULL,NULL,'index,follow',NULL,NULL,NULL,NULL,NULL,NULL,'WebApplication',NULL,'Working Hours Calculator'),
(4,'tool',4,'Business Days Calculator — Free Online Tool','Count the number of business days (excluding weekends) between two dates.','business days calculator',NULL,NULL,'index,follow',NULL,NULL,NULL,NULL,NULL,NULL,'WebApplication',NULL,'Business Days Calculator'),
(5,'tool',5,'EOQ Calculator — Free Online Tool','Find the Economic Order Quantity that minimizes total inventory cost.','eoq calculator',NULL,NULL,'index,follow',NULL,NULL,NULL,NULL,NULL,NULL,'WebApplication',NULL,'EOQ Calculator'),
(6,'tool',6,'Reorder Point Calculator — Free Online Tool','Find the inventory level at which you should place a new order.','reorder point calculator',NULL,NULL,'index,follow',NULL,NULL,NULL,NULL,NULL,NULL,'WebApplication',NULL,'Reorder Point Calculator'),
