INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `status`, `is_system`, `created_at`, `updated_at`) VALUES (1,'About Us','about','<p>ToolStack is a free online tools platform offering calculators, converters and generators for professionals, students and everyday use.</p>','published',1,'2026-09-11 06:53:03','2026-09-11 06:53:03'),
(2,'Contact Us','contact','<p>Reach us at <a href=\"mailto:hello@example.com\">hello@example.com</a>.</p>','published',1,'2026-09-11 06:53:03','2026-09-11 06:53:03'),
(3,'Privacy Policy','privacy-policy','<p>We do not require registration to use our tools. Calculation inputs are processed in your browser and are not transmitted to our servers unless a tool explicitly states otherwise.</p>','published',1,'2026-09-11 06:53:03','2026-09-11 06:53:03'),
(4,'Terms of Service','terms','<p>Tools are provided \"as is\" for informational purposes. See our Disclaimer for important limitations.</p>','published',1,'2026-09-11 06:53:03','2026-09-11 06:53:03'),
(5,'Disclaimer','disclaimer','<p>Results are estimates for informational purposes only and should not be considered professional financial, engineering, tax, medical, or legal advice.</p>','published',1,'2026-09-11 06:53:03','2026-09-11 06:53:03'),
(6,'Cookie Policy','cookie-policy','<p>We use only strictly necessary session cookies and, where you opt in, browser localStorage for theme preference and favorites.</p>','published',1,'2026-09-11 06:53:03','2026-09-11 06:53:03'),
(7,'Frequently Asked Questions','faq','<p>All tools are free to use and require no registration. See each tool\'s own FAQ section for tool-specific questions.</p>','published',1,'2026-09-11 06:53:03','2026-09-11 06:53:03');
